-- Lightweight project changes, including same-length edits made in another window.
CREATE TABLE project_change_clock(project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,revision INTEGER NOT NULL DEFAULT 0,materials INTEGER NOT NULL DEFAULT 0,project_data INTEGER NOT NULL DEFAULT 0,bibliography INTEGER NOT NULL DEFAULT 0,presentation INTEGER NOT NULL DEFAULT 0,manuscripts INTEGER NOT NULL DEFAULT 0,reading INTEGER NOT NULL DEFAULT 0);
CREATE TRIGGER writing_clock_projects_insert AFTER INSERT ON projects WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.id) BEGIN INSERT INTO project_change_clock(project_id,revision,project_data) VALUES(NEW.id,1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,project_data=project_data+1; END;
CREATE TRIGGER writing_clock_projects_update AFTER UPDATE ON projects WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.id) BEGIN INSERT INTO project_change_clock(project_id,revision,project_data) VALUES(NEW.id,1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,project_data=project_data+1; END;
CREATE TRIGGER writing_clock_files_insert AFTER INSERT ON files WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id) BEGIN INSERT INTO project_change_clock(project_id,revision,materials) VALUES(NEW.project_id,1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,materials=materials+1; END;
CREATE TRIGGER writing_clock_files_update AFTER UPDATE ON files WHEN EXISTS(SELECT 1 FROM projects WHERE id=NEW.project_id) BEGIN INSERT INTO project_change_clock(project_id,revision,materials) VALUES(NEW.project_id,1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,materials=materials+1; END;
CREATE TRIGGER writing_clock_files_delete AFTER DELETE ON files WHEN EXISTS(SELECT 1 FROM projects WHERE id=OLD.project_id) BEGIN INSERT INTO project_change_clock(project_id,revision,materials) VALUES(OLD.project_id,1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,materials=materials+1; END;
CREATE TRIGGER writing_clock_pages_insert AFTER INSERT ON pages WHEN EXISTS(SELECT 1 FROM projects WHERE id=(SELECT project_id FROM files WHERE id=NEW.file_id)) BEGIN INSERT INTO project_change_clock(project_id,revision,materials) VALUES((SELECT project_id FROM files WHERE id=NEW.file_id),1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,materials=materials+1; END;
