CREATE TRIGGER writing_clock_pages_delete AFTER DELETE ON pages WHEN EXISTS(SELECT 1 FROM projects WHERE id=(SELECT project_id FROM files WHERE id=OLD.file_id)) BEGIN INSERT INTO project_change_clock(project_id,revision,materials) VALUES((SELECT project_id FROM files WHERE id=OLD.file_id),1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,materials=materials+1; END;
