CREATE TRIGGER writing_clock_settings_insert AFTER INSERT ON settings WHEN (NEW.key GLOB 'format:*' OR NEW.key GLOB 'template:*' OR NEW.key GLOB 'figure_policy:*') AND EXISTS(SELECT 1 FROM projects WHERE id=substr(NEW.key,instr(NEW.key,':')+1)) BEGIN INSERT INTO project_change_clock(project_id,revision,presentation) VALUES(substr(NEW.key,instr(NEW.key,':')+1),1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,presentation=presentation+1; END;
CREATE TRIGGER writing_clock_settings_update AFTER UPDATE ON settings WHEN (NEW.key GLOB 'format:*' OR NEW.key GLOB 'template:*' OR NEW.key GLOB 'figure_policy:*') AND EXISTS(SELECT 1 FROM projects WHERE id=substr(NEW.key,instr(NEW.key,':')+1)) BEGIN INSERT INTO project_change_clock(project_id,revision,presentation) VALUES(substr(NEW.key,instr(NEW.key,':')+1),1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,presentation=presentation+1; END;
CREATE TRIGGER writing_clock_settings_delete AFTER DELETE ON settings WHEN (OLD.key GLOB 'format:*' OR OLD.key GLOB 'template:*' OR OLD.key GLOB 'figure_policy:*') AND EXISTS(SELECT 1 FROM projects WHERE id=substr(OLD.key,instr(OLD.key,':')+1)) BEGIN INSERT INTO project_change_clock(project_id,revision,presentation) VALUES(substr(OLD.key,instr(OLD.key,':')+1),1,1) ON CONFLICT(project_id) DO UPDATE SET revision=revision+1,presentation=presentation+1; END;
